"""Discount calculation module."""

from decimal import Decimal, InvalidOperation
from typing import Union


def apply_discount(price: Union[int, float, Decimal], percentage: Union[int, float, Decimal]) -> float:
    """Apply a percentage discount to a price."""
    try:
        price_decimal = Decimal(str(price))
        percent_decimal = Decimal(str(percentage))
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError("Price and percentage must be valid numbers")

    if price_decimal < 0:
        raise ValueError("Price cannot be negative")
    if percent_decimal < 0:
        raise ValueError("Discount percentage cannot be negative")
    if percent_decimal > 100:
        raise ValueError("Discount percentage cannot exceed 100%")

    discount_amount = price_decimal * (percent_decimal / Decimal('100'))
    result = price_decimal - discount_amount
    return float(result)
